 float End=Y2+563;U.Card(0,End,W,168,"Renderer scale");U.Slider(24,End+61,(W-64)/2,"Brightness");U.Slider(40+(W-64)/2,End+61,(W-64)/2,"Point Size");U.Wrap(24,End+129,W-48,"The chart omits atmosphere and daylight extinction. The pole dial is a schematic.");End+=184;U.Card(0,End,W,184,"Baking / star atlas");U.Tile(24,End+54,(W-56)/2,"Bake",nullptr);U.Tile(32+(W-56)/2,End+54,(W-56)/2,"Use baked",nullptr);U.Wrap(24,End+137,W-48,"Star-atlas baking and playback are not implemented. The renderer uses the live catalogue.");ImGui::SetCursorScreenPos(U.At(0,End+206));ImGui::Dummy({W,1});ImGui::PopFont();
